fn sqlite_semantic_run_complete_sql_cells_are_exact_for_both_triggers_and_all_ieee_branches(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../\u{1f9eb}\uFE0Ffixtures/\u{1fab6}\uFE0Fsqlite/\u{1f4cf}\uFE0Fsemantic-cells/\u{1f523}\uFE0F.json")).unwrap();for case in law["cases"].as_array().unwrap(){let name=case["name"].as_str().unwrap();let mut expected=source();if name.len()==16&&name.bytes().all(|byte|byte.is_ascii_hexdigit()){let bits=u64::from_str_radix(name,16).unwrap();for node in&mut expected.node_records{node.duration_ms=f64::from_bits(bits)}}else if name!="base"{let(kind,finished)=name.split_once('-').unwrap();let fixture=laws();let trigger=fixture["triggers"].as_array().unwrap().iter().find(|trigger|trigger["kind"]==kind).unwrap();expected.trigger=match kind{"manual"=>RunTrigger::Manual{actor:trigger["actor"].as_str().unwrap().into()},"automation"=>RunTrigger::Automation{automation_ref:trigger["automationRef"].as_str().unwrap().into(),event_fingerprint:trigger["eventFingerprint"].as_str().unwrap().into()},_=>panic!("closed trigger")};expected.finished_at=match finished{"absent"=>None,"empty"=>Some(String::new()),"unicode"=>Some("\0\u{1f600}".into()),_=>panic!("closed finished presence")};}
  let bytes=usize::try_from(case["bytes"].as_u64().unwrap()).unwrap();let defaults=SqliteDatabaseLimits::default();let d=database(&expected);assert_eq!(d.tables.len(),usize::try_from(law["tables"].as_u64().unwrap()).unwrap());assert_eq!(d.tables.iter().map(|table|table.rows.len()).sum::<usize>(),usize::try_from(law["rows"].as_u64().unwrap()).unwrap());
  for allowance in[bytes,bytes-1]{let limits=SqliteDatabaseLimits{max_value_bytes:allowance,..defaults};let projected=expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits));assert_eq!(projected.is_ok(),allowance==bytes,"project {name}");let restored=RunArtifact::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,limits));assert_eq!(restored.is_ok(),allowance==bytes,"reconstruct {name}");if allowance==bytes{run_cell_equal(&restored.unwrap(),&expected);}for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let encoded=expected.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits));assert_eq!(encoded.is_ok(),allowance==bytes,"encode {name} {encoding:?}");let decoded=RunArtifact::decode_sqlite_snapshot_native(&payload(&expected,encoding),&mut SqliteSnapshotControl::new(&mut |_|true,limits));assert_eq!(decoded.is_ok(),allowance==bytes,"decode {name} {encoding:?}");if allowance==bytes{run_cell_equal(&decoded.unwrap(),&expected);}}}
  println!("[DEBUG] Run complete native SQL cells case={name} bytes={bytes}");
 }
}
